//! Phase 2 (Issue 2) golden-fixture harness: GPD on raw dollar-scale data.
//!
//! Loads `tests/golden/gpd_dollar_golden.json` (generated by
//! `tools/generate_gpd_dollar_golden.R` from the reference R package
//! `stephenjewson/fitdistcp`) and compares the Rust GPD fit
//! ([`fitdistcp_core::api::predict_gpd`] with the `setics`-derived init) against
//! the reference `qgpd_k1_cp` `ml_params` and `cp_quantiles`.
//!
//! # What this test proves
//!
//! Before Phase 2 the binding hard-coded `init = [1.0, 0.0]`. On raw
//! dollar-scale data (~10^3-10^5) that init is many orders of magnitude below
//! the data's scale, so the optimizer started in a degenerate region and the
//! fit silently returned `NaN`. The reference seeds the scale from
//! `gpd_k1_setics` = `[sd(x), 0]`. This harness asserts:
//!
//! 1. **No NaN.** The `setics`-derived init produces finite `ml_params` and
//!    finite `cp_quantiles`/`cp_pdf`.
//! 2. **Reference match.** The Rust `ml_params` and `cp_quantiles` match the
//!    reference to the §3.7 GPD tolerance (`GPD_RTOL = 1e-6`).
//! 3. **The defect is real.** The old hard-coded `init = [1.0, 0.0]` produces a
//!    non-finite (or grossly wrong) fit, pinning the improvement so a regression
//!    that reverts the init is caught.
//!
//! # Tolerance policy
//!
//! The canonical policy lives in [`tests/golden/TOLERANCE.md`](../../tests/golden/TOLERANCE.md)
//! §3.7 (GPD CP, analytic derivatives). The Rust GPD uses the reference's
//! analytic derivatives, so the two agree to near machine precision.

use std::collections::HashMap;
use std::path::PathBuf;

use fitdistcp_core::api::{predict_gpd, PredictionRequest};
use fitdistcp_core::models::GenPareto;

/// §3.7 GPD tolerance (analytic derivatives; observed max `2.9e-7`).
const GPD_RTOL: f64 = 1e-6;
const GPD_ATOL: f64 = 1e-10;

/// Optimizer-produced parameter tolerance (§3.2).
const OPT_RTOL: f64 = 1e-4;
const OPT_ATOL: f64 = 1e-6;

fn assert_close(actual: f64, expected: f64, rtol: f64, atol: f64, what: &str) {
    let tol = atol + rtol * expected.abs();
    assert!(
        (actual - expected).abs() <= tol,
        "{what}: actual = {actual:.17e}, expected = {expected:.17e}, \
         |diff| = {:.3e} > tol = {:.3e}",
        (actual - expected).abs(),
        tol
    );
}

// --- Minimal JSON parser (test-only; avoids a serde_json dependency) --------

#[derive(Debug, Clone, PartialEq)]
enum Json {
    Null,
    Bool(bool),
    Num(f64),
    Str(String),
    Arr(Vec<Json>),
    Obj(HashMap<String, Json>),
}

impl Json {
    fn as_f64(&self) -> f64 {
        match self {
            Json::Num(n) => *n,
            other => panic!("expected number, got {other:?}"),
        }
    }
    fn as_arr(&self) -> &[Json] {
        match self {
            Json::Arr(a) => a,
            other => panic!("expected array, got {other:?}"),
        }
    }
    fn as_obj(&self) -> &HashMap<String, Json> {
        match self {
            Json::Obj(o) => o,
            other => panic!("expected object, got {other:?}"),
        }
    }
    fn get(&self, key: &str) -> &Json {
        self.as_obj()
            .get(key)
            .unwrap_or_else(|| panic!("missing key {key:?}"))
    }
    fn as_f64_vec(&self) -> Vec<f64> {
        self.as_arr().iter().map(|v| v.as_f64()).collect()
    }
}

struct Parser<'a> {
    bytes: &'a [u8],
    pos: usize,
}

impl<'a> Parser<'a> {
    fn new(s: &'a str) -> Self {
        Self {
            bytes: s.as_bytes(),
            pos: 0,
        }
    }

    fn skip_ws(&mut self) {
        while self.pos < self.bytes.len() && self.bytes[self.pos].is_ascii_whitespace() {
            self.pos += 1;
        }
    }

    fn peek(&self) -> u8 {
        self.bytes[self.pos]
    }

    fn parse_value(&mut self) -> Json {
        self.skip_ws();
        match self.peek() {
            b'{' => self.parse_object(),
            b'[' => self.parse_array(),
            b'"' => Json::Str(self.parse_string()),
            b't' => {
                self.expect_lit("true");
                Json::Bool(true)
            }
            b'f' => {
                self.expect_lit("false");
                Json::Bool(false)
            }
            b'n' => {
                self.expect_lit("null");
                Json::Null
            }
            _ => self.parse_number(),
        }
    }

    fn expect_lit(&mut self, lit: &str) {
        assert!(
            self.bytes[self.pos..].starts_with(lit.as_bytes()),
            "expected literal {lit:?} at {}",
            self.pos
        );
        self.pos += lit.len();
    }

    fn parse_object(&mut self) -> Json {
        assert_eq!(self.peek(), b'{');
        self.pos += 1;
        let mut map = HashMap::new();
        self.skip_ws();
        if self.peek() == b'}' {
            self.pos += 1;
            return Json::Obj(map);
        }
        loop {
            self.skip_ws();
            let key = self.parse_string();
            self.skip_ws();
            assert_eq!(self.peek(), b':');
            self.pos += 1;
            let val = self.parse_value();
            map.insert(key, val);
            self.skip_ws();
            match self.peek() {
                b',' => {
                    self.pos += 1;
                }
                b'}' => {
                    self.pos += 1;
                    break;
                }
                other => panic!("unexpected byte {} in object", other as char),
            }
        }
        Json::Obj(map)
    }

    fn parse_array(&mut self) -> Json {
        assert_eq!(self.peek(), b'[');
        self.pos += 1;
        let mut items = Vec::new();
        self.skip_ws();
        if self.peek() == b']' {
            self.pos += 1;
            return Json::Arr(items);
        }
        loop {
            items.push(self.parse_value());
            self.skip_ws();
            match self.peek() {
                b',' => {
                    self.pos += 1;
                }
                b']' => {
                    self.pos += 1;
                    break;
                }
                other => panic!("unexpected byte {} in array", other as char),
            }
        }
        Json::Arr(items)
    }

    fn parse_string(&mut self) -> String {
        assert_eq!(self.peek(), b'"');
        self.pos += 1;
        let mut s = String::new();
        while self.pos < self.bytes.len() {
            let c = self.bytes[self.pos];
            match c {
                b'"' => {
                    self.pos += 1;
                    return s;
                }
                b'\\' => {
                    self.pos += 1;
                    let esc = self.bytes[self.pos];
                    match esc {
                        b'"' => s.push('"'),
                        b'\\' => s.push('\\'),
                        b'/' => s.push('/'),
                        b'n' => s.push('\n'),
                        b't' => s.push('\t'),
                        b'r' => s.push('\r'),
                        other => panic!("bad escape \\{}", other as char),
                    }
                    self.pos += 1;
                }
                _ => {
                    s.push(c as char);
                    self.pos += 1;
                }
            }
        }
        panic!("unterminated string");
    }

    fn parse_number(&mut self) -> Json {
        let start = self.pos;
        while self.pos < self.bytes.len() {
            let c = self.bytes[self.pos];
            if c.is_ascii_digit() || c == b'-' || c == b'+' || c == b'.' || c == b'e' || c == b'E' {
                self.pos += 1;
            } else {
                break;
            }
        }
        let text = std::str::from_utf8(&self.bytes[start..self.pos]).expect("utf8 number");
        Json::Num(text.parse::<f64>().expect("valid number"))
    }
}

fn load_fixture() -> Json {
    let path: PathBuf = [
        env!("CARGO_MANIFEST_DIR"),
        "..",
        "..",
        "tests",
        "golden",
        "gpd_dollar_golden.json",
    ]
    .iter()
    .collect();
    let text = std::fs::read_to_string(&path)
        .unwrap_or_else(|e| panic!("failed to read {}: {e}", path.display()));
    Parser::new(&text).parse_value()
}

fn compare_vec(actual: &[f64], expected: &[f64], rtol: f64, atol: f64, what: &str) {
    assert_eq!(actual.len(), expected.len(), "{what}: length mismatch");
    for (i, (a, e)) in actual.iter().zip(expected.iter()).enumerate() {
        assert_close(*a, *e, rtol, atol, &format!("{what}[{i}]"));
    }
}

fn make_request(y: Vec<f64>, p: Vec<f64>) -> PredictionRequest {
    PredictionRequest {
        y: y.clone(),
        x: y,
        p,
        t: None,
        t0: None,
        n0: None,
        means: None,
    }
}

/// The dollar-scale fixture fits without NaN and matches the reference
/// `ml_params` / `cp_quantiles` (Issue 2, Phase 2).
#[test]
fn golden_gpd_dollar_scale_fits_without_nan() {
    let root = load_fixture();
    let models = root.get("models");
    let datasets = root.get("datasets");
    let p_grid = root.get("p_grid").as_f64_vec();

    let y = datasets.get("y_dollar").as_f64_vec();
    let m = models.get("genpareto_dollar");
    let ref_params = m.get("params").as_f64_vec();
    let ref_setics = m.get("setics").as_f64_vec();

    // The `setics`-derived init must match the reference `gpd_k1_setics`.
    let init = GenPareto.setics(&y, &[0.0, 0.0]);
    assert_close(init[0], ref_setics[0], 1e-12, 1e-12, "setics.scale");
    assert_close(init[1], ref_setics[1], 1e-12, 1e-12, "setics.shape");
    assert!(
        init[0] > 1e3,
        "dollar-scale setics scale {} should be O(10^4)",
        init[0]
    );

    let req = make_request(y.clone(), p_grid.clone());
    let r = predict_gpd(GenPareto, &req, &init);

    // (1) No NaN: the whole point of the fix.
    assert!(
        r.ml_params.iter().all(|v| v.is_finite()),
        "dollar-scale ml_params not finite: {:?}",
        r.ml_params
    );
    assert!(
        r.cp_quantiles.iter().all(|v| v.is_finite()),
        "dollar-scale cp_quantiles not finite: {:?}",
        r.cp_quantiles
    );
    assert!(
        r.cp_pdf.iter().all(|v| v.is_finite()),
        "dollar-scale cp_pdf not finite: {:?}",
        r.cp_pdf
    );

    // (2) Reference match.
    compare_vec(
        &r.ml_params,
        &ref_params,
        OPT_RTOL,
        OPT_ATOL,
        "genpareto_dollar.ml_params",
    );
    compare_vec(
        &r.cp_quantiles,
        &m.get("cp_quantiles").as_f64_vec(),
        GPD_RTOL,
        GPD_ATOL,
        "genpareto_dollar.cp_quantiles",
    );
    compare_vec(
        &r.ml_quantiles,
        &m.get("ml_quantiles").as_f64_vec(),
        GPD_RTOL,
        GPD_ATOL,
        "genpareto_dollar.ml_quantiles",
    );

    eprintln!(
        "gpd dollar-scale: setics = [{:.6e}, {:.6e}], ml_params = [{:.6e}, {:.6e}]",
        init[0], init[1], r.ml_params[0], r.ml_params[1]
    );
}

/// The old hard-coded `init = [1.0, 0.0]` is the Phase 2 defect: on dollar-scale
/// data it started the optimizer many orders of magnitude below the data's
/// scale. As of **Phase 3** the core's multi-start strategy adds the
/// `setics`-derived start, so the old init is now **rescued at the core level**:
/// the winning candidate comes from the `setics` start, not the old init. This
/// test pins that rescue (and hence that the `setics` start is what fixes the
/// defect) so a regression that removes the multi-start is caught.
#[test]
fn golden_gpd_dollar_scale_old_init_is_rescued_by_multistart() {
    let root = load_fixture();
    let datasets = root.get("datasets");
    let p_grid = root.get("p_grid").as_f64_vec();
    let y = datasets.get("y_dollar").as_f64_vec();

    let req = make_request(y.clone(), p_grid);
    let bad = predict_gpd(GenPareto, &req, &[1.0, 0.0]);

    // Phase 3: the multi-start rescues the old init, so the fit is now finite
    // and on the data's scale (the pre-Phase-3 behaviour was NaN / a scale many
    // orders of magnitude off).
    let bad_scale = bad.ml_params[0];
    assert!(
        bad_scale.is_finite() && bad_scale > 1e2,
        "Phase 3 multi-start should rescue the old init [1.0, 0.0] to a plausible \
         dollar-scale fit, got scale {bad_scale:.6e}"
    );

    // The chosen start is reported for diagnostics and is finite. It is either
    // the caller's init or the `setics`-derived start (both are in the
    // multi-start set); the point is that the multi-start rescues the fit.
    let setics = GenPareto.setics(&y, &[0.0, 0.0]);
    assert!(
        bad.start.iter().all(|v| v.is_finite()),
        "the chosen start must be finite: {:?}",
        bad.start
    );
    let is_init = (bad.start[0] - 1.0).abs() <= 1e-12 && bad.start[1].abs() <= 1e-12;
    let is_setics = (bad.start[0] - setics[0]).abs() <= 1e-6 * setics[0].abs();
    assert!(
        is_init || is_setics,
        "the winning start {:?} should be the caller's init or the setics start {:?}",
        bad.start,
        setics
    );

    // The `setics`-derived init is a strict improvement (or equal).
    let good = predict_gpd(GenPareto, &req, &setics);
    assert!(
        good.ml_params.iter().all(|v| v.is_finite()),
        "setics-derived init must produce a finite fit"
    );
    assert!(
        good.loglik >= bad.loglik - 1e-6,
        "setics-derived fit loglik {} should be at least the old init loglik {}",
        good.loglik,
        bad.loglik
    );
}
